DROP TABLE IF EXISTS `scrabble_games_initial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `scrabble_games_initial` (
  `gameid` int(11) DEFAULT NULL,
  `tourneyid` int(11) DEFAULT NULL,
  `tie` char(6) DEFAULT NULL,
  `winnerid` int(11) DEFAULT NULL,
  `winnername` varchar(50) DEFAULT NULL,
  `winnerscore` int(11) DEFAULT NULL,
  `winneroldrating` int(11) DEFAULT NULL,
  `winnernewrating` int(11) DEFAULT NULL,
  `winnerpos` int(11) DEFAULT NULL,
  `loserid` int(11) DEFAULT NULL,
  `losername` varchar(50) DEFAULT NULL,
  `loserscore` int(11) DEFAULT NULL,
  `loseroldrating` int(11) DEFAULT NULL,
  `losernewrating` int(11) DEFAULT NULL,
  `loserpos` int(11) DEFAULT NULL,
  `round` int(11) DEFAULT NULL,
  `division` int(11) DEFAULT NULL,
  `date` varchar(50) DEFAULT NULL,
  `lexicon` char(6) DEFAULT NULL,
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `winnerSysId` int(11) NOT NULL DEFAULT -1,
  `loserSysId` int(11) NOT NULL DEFAULT -1,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=5790 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
